export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;

  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  // Time is elapsed from launch. The timeline duration is 2 * apexTime max roughly.
  // Actually timeline duration covers from launch (t=0) to twice apexTime.
  const t = Math.max(0, Math.min(time, 2 * apexTime));

  const tossedHeight = launchSpeed * t - 0.5 * gravity * t * t;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;

  // Drop ball held at apex until apexTime, then falls freely from rest
  let dropHeight, dropVelocity, dropAcceleration;
  if (t < apexTime) {
    dropHeight = apexHeight;
    dropVelocity = 0;
    dropAcceleration = 0;
  } else {
    const dt = t - apexTime;
    dropHeight = apexHeight - 0.5 * gravity * dt * dt;
    dropVelocity = -gravity * dt;
    dropAcceleration = -gravity;
  }

  // States
  let tossState = "At launch";
  if (t > 0.02 && t < apexTime - 0.02) tossState = "Rising";
  else if (Math.abs(t - apexTime) <= 0.02) tossState = "At the top";
  else if (t > apexTime + 0.02 && tossedHeight > 0.02) tossState = "Falling";
  else if (t >= apexTime && tossedHeight <= 0.02) tossState = "At launch height";

  let dropState = "Held in place";
  if (Math.abs(t - apexTime) <= 0.02) dropState = "Just released";
  else if (t > apexTime && dropHeight > 0.02) dropState = "Falling together";
  else if (t > apexTime && dropHeight <= 0.02) dropState = "At launch height";

  // Layout coordinates (640 x 420)
  // Two lanes side by side: x: 40 to 300 (toss), x: 340 to 600 (drop)
  // y scale: height 0 to 2.2 m mapped to pixel y from 340 (bottom) to 80 (top)
  const scaleY = (h) => 340 - (h / 2.2) * 260;

  const objects = [];

  // Lanes
  objects.push(...sdk.panel({ x: 40, y: 50, w: 260, h: 310, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 340, y: 50, w: 260, h: 310, title: "Drop lane", state: dropState, id: "lane.drop" }));

  // Axes inside lanes (height axis y)
  objects.push(sdk.axis("axis.toss", { x: 70, y: 340, length: 260, orientation: "y", min: 0, max: 2.2, ticks: [0, 1.1, 2.2], label: "Height", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: 370, y: 340, length: 260, orientation: "y", min: 0, max: 2.2, ticks: [0, 1.1, 2.2], label: "Height", unit: "m" }));

  // Balls
  const tossY = scaleY(Math.max(0, tossedHeight));
  const dropY = scaleY(Math.max(0, dropHeight));

  objects.push(sdk.circle("ball.toss", 170, tossY, 24, { role: "output" }));
  objects.push(sdk.circle("ball.drop", 470, dropY, 24, { role: "output" }));

  // Gate at apex height in drop lane
  const gateY = scaleY(apexHeight);
  const gateOpen = t >= apexTime;
  objects.push(...sdk.gate("gate", 470, gateY, { open: gateOpen, w: 40, label: gateOpen ? "Open" : "Held" }));

  // Vectors: velocity (blue) and acceleration (warm dashed)
  // up positive means vector direction "up" or "down"
  objects.push(...sdk.vector("vec.v.toss", { x: 140, y: tossY }, { value: tossedVelocity, direction: "up" }, { scale: 15, label: "v", role: "output" }));
  objects.push(...sdk.vector("vec.a.toss", { x: 200, y: tossY }, { value: tossedAcceleration, direction: "up" }, { scale: 5, label: "a", role: "warning" }));

  objects.push(...sdk.vector("vec.v.drop", { x: 440, y: dropY }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v", role: "output" }));
  objects.push(...sdk.vector("vec.a.drop", { x: 500, y: dropY }, { value: dropAcceleration, direction: "up" }, { scale: 5, label: "a", role: "warning" }));

  // Callouts
  objects.push(...sdk.callout(90, tossY - 30, [
    "v: " + sdk.format(tossedVelocity, 2) + " m/s",
    "a: " + sdk.format(tossedAcceleration, 1) + " m/s^2"
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(390, dropY - 30, [
    "v: " + sdk.format(dropVelocity, 2) + " m/s",
    "a: " + sdk.format(dropAcceleration, 1) + " m/s^2"
  ], { id: "callout.drop" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
